export function tableArt(cityId) {
  const { silhouette, landmarks, details, accents } = Object.hasOwn(CITY_ART, cityId) ? CITY_ART[cityId] : CITY_ART.quito;
  return `<svg class="table-city-art" viewBox="0 0 720 240" aria-hidden="true" focusable="false">
    <g fill="currentColor" opacity=".16">${silhouette}</g>
    <g fill="currentColor" opacity=".38">${accents}</g>
    <g fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round">
      <g stroke-width="2.8">${landmarks}</g>
      <g stroke-width="1.55" opacity=".82">${details}</g>
    </g>
  </svg>`;
}
